//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::uint::uint8_log2`; the
//! native twin is `benches/native/Bench/Uint8Log2.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::uint;
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(uint::uint8_log2((x >> 56) as u8) as u64);
    }
    acc as u64
}

fn main() {
    run(|| (), kernel)
}
